1	/**
2	 * OAuth 2.0 ユーティリティ関数
3	 * JWT トークンの生成・検証、PKCE、ランダム文字列生成など
4	 */
5	
6	import jwt from 'jsonwebtoken';
7	import crypto from 'crypto';
8	import bcrypt from 'bcryptjs';
9	
10	// 環境変数から JWT シークレットキーを取得
11	const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';
12	const JWT_ISSUER = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';
13	
14	// トークン有効期限
15	export const TOKEN_EXPIRY = {
16	  ACCESS_TOKEN: 60 * 60 * 24 * 30, // 30日（秒）
17	  AUTHORIZATION_CODE: 60 * 10, // 10分（秒）
18	};
19	
20	/**
21	 * ランダムな文字列を生成（client_id, client_secret, codeなど）
22	 */
23	export function generateRandomString(length: number = 32): string {
24	  return crypto.randomBytes(length).toString('hex');
25	}
26	
27	/**
28	 * Client Secret をハッシュ化
29	 */
30	export async function hashClientSecret(secret: string): Promise<string> {
31	  return bcrypt.hash(secret, 10);
32	}
33	
34	/**
35	 * Client Secret を検証
36	 */
37	export async function verifyClientSecret(
38	  secret: string,
39	  hash: string
40	): Promise<boolean> {
41	  return bcrypt.compare(secret, hash);
42	}
43	
44	/**
45	 * PKCE code_challenge を検証
46	 */
47	export function verifyCodeChallenge(
48	  verifier: string,
49	  challenge: string,
50	  method: string = 'S256'
51	): boolean {
52	  if (method !== 'S256') {
53	    return false;
54	  }
55	
56	  const hash = crypto
57	    .createHash('sha256')
58	    .update(verifier)
59	    .digest('base64url');
60	
61	  return hash === challenge;
62	}
63	
64	/**
65	 * JWT アクセストークンを生成
66	 */
67	export interface JWTPayload {
68	  sub: string; // user_id
69	  display_name: string;
70	  discord_id: string;
71	  generation: number;
72	  status: number;
73	  scope: string;
74	}
75	
76	export function generateAccessToken(
77	  payload: JWTPayload,
78	  clientId: string
79	): string {
80	  const now = Math.floor(Date.now() / 1000);
81	
82	  return jwt.sign(
83	    {
84	      ...payload,
85	      iss: JWT_ISSUER,
86	      aud: clientId,
87	      iat: now,
88	      exp: now + TOKEN_EXPIRY.ACCESS_TOKEN,
89	    },
90	    JWT_SECRET,
91	    { algorithm: 'HS256' }
92	  );
93	}
94	
95	/**
96	 * JWT アクセストークンを検証・デコード
97	 */
98	export function verifyAccessToken(token: string, clientId?: string): JWTPayload | null {
99	  try {
100	    const decoded = jwt.verify(token, JWT_SECRET, {
101	      algorithms: ['HS256'],
102	      issuer: JWT_ISSUER,
103	      audience: clientId,
